INSERT INTO "concerns" ("id", "slug", "user_id", "title", "image", "description", "links", "status", "created_at", "updated_at", "order") VALUES
(1, 'abce3fa0-bf65-4a0f-ab12-ae7eacb7950b', 1, 'TECHNICAL ASSOCIATES SERVICES P. LTD.', '16e2cbe7-ee87-4b7e-8b1f-be6229566efc.webp', '<p>Technical Associates Services P. Ltd. was formed in the year 2002 with an aim to provide cost-effective engineering solutions to Nepalese people across the commercial and health care sectors.<br></p><p>We provide complete solutions for Water Treatment Systems, Waste Treatment Systems, Water Treatment Accessories, Water Heating Systems, Pharma water distribution systems, Pumping Solutions, Compressed Air Systems, Medical Gas Pipeline Systems, Sprinklers &amp; Irrigation Systems, Professional Laundry solutions, PSA type Oxygen &amp; Nitrogen Generators, Modular Operation Theatres, Fire Fighting Systems, and Flowmeters.</p>', 'https://tas.com.np/', 1, '2024-03-18 06:48:40', '2025-09-16 00:23:54', 0),
(3, '4c9de9d6-94a5-4439-ace4-2f1dcd7ee93e', 2, 'HEALTHCARE TECHNOLOGIES PVT.LTD.', '32278386-b822-4660-ba83-05e07cd4d786.webp', '<p>Healthcare Technologies was formed in the year 2003. We''re one of the leading trading company involved in importing and distributing healthcare products across Nepal. We are the exclusive distributor of 3M, Microlife, Paramount Bed, Lifotronic, Dr Care, Fia Biomed &amp; some more.</p>', 'https://healthcare.com.np/', 1, '2024-04-26 08:29:56', '2025-09-16 00:27:02', 0),
(6, 'e236efdf-39c5-40cb-8446-496da51635a7', 2, 'Future Techniques Pvt. Ltd.', 'eb27811c-a263-4876-8410-e596b308c3b1.webp', '<p>Future Techniques Pvt. Ltd. is an engineering company based in Kathmandu, Nepal, specializing in providing industrial solutions, turnkey systems, and stainless steel components. They offer a range of services, including project planning, engineering, installation, and commissioning for clients across Nepal, with a focus on quality, safety, and customer satisfaction. The company also handles plant upgrades, service contracts, and provides technical support for industrial machinery like steam boilers and water treatment plants.</p>', 'https://futuretech-9a6a3.web.app/', 1, '2024-09-04 09:38:11', '2025-09-16 00:25:44', 0),
(7, 'd420ff2b-84a5-4e77-81c9-08eea81a8a29', 2, 'SUN MEDICAL CONCERN PVT.LTD', '9d79009f-99eb-4c82-ba37-838c602ee73a.webp', '<p>It is one of the leading business houses, which provide solutions for Healthcare Sectors. It deals with Medical Equipment, Medical Consumables, specialty healthcare solutions etc.</p><p>Major representations are :&nbsp; </p><ul><li>GE Healthcare (Medical Equipments)</li><li>Paramount Beds (Hospital Furnitures)<br><br></li></ul>', 'http://www.healthcare.com.np/', 0, '2024-09-22 05:11:31', '2024-10-03 10:28:07', 0);
