(3, 'fa6af225-72c3-45fe-8a27-9a2a1bab1060', 'Something', 'something@gmail.com', '9880227545', 'Something', 'Something', '2024-09-19 22:17:13', '2024-09-19 22:17:13'),
(4, '3726010f-d172-4648-be78-c278ede083de', 'Something', 'something@gmail.com', '9880227545', 'Something', 'Something', '2024-09-19 22:17:42', '2024-09-19 22:17:42'),
(6, 'e5b499ff-9828-42a4-a28e-9e090e63661b', 'kravchenko Oleg', 'spagnolidmtgroup@zohomail.eu', '2025650128', 'order request', 'Hello there,\n\nI have been introduced to your company by a partner.\n\nI sent you an email earlier, but I never got a response. Maybe I\nentered the wrong address. kindly put me in contact with your\nsales representative.\n\nBest Regards,\nkravchenko Oleg\nInternational Sales Representative', '2024-09-30 14:04:11', '2024-09-30 14:04:11'),
(7, 'e19d6fbf-abd8-4c2a-805b-ecfdefa4741f', 'Bijay Tandukar', 'jbaa1970@yahoo.com', '9841290268', 'Pipe', 'Please  give me a call thank you.', '2024-10-01 02:08:35', '2024-10-01 02:08:35'),
(8, 'c91edbd7-b9a5-4b70-a426-2c79106ba370', 'Sanjog Lal Singh', 'slsingh048@gmail.com', '9841474066', 'Floor heating portable', 'My client needs floor heating in toilet that can be taken off in summer easily. Is it possible?? I need to talk before going to client house.', '2024-10-05 21:11:18', '2024-10-05 21:11:18'),
(9, 'a179f7ae-8263-43e4-9b19-5f8c75e5613c', 'Adelya', 'mavila8221@crodity.com', '9845372524', 'payment', '939rtrhjfjwoeqejnfsqled', '2024-10-20 05:29:22', '2024-10-20 05:29:22'),
(10, 'e714bb5b-74bc-4372-9680-e8a8a0f70d98', 'Benjamin', 'benjamin@innorix.com', '0333594991', 'INNORIX LLC Partnership', 'Hi there,\nMy name is Benjamin, and I represent INNORIX. With over 25 years of experience and more than 500 global partners, we''ve had the honor of collaborating with esteemed government clients such as the United States Army and Hanwha Defense, as well as industry leaders like Volkswagen, Hyundai, Samsung, and LG.\nWe are looking to expand into the Nepal market and would greatly appreciate your expertise in navigating this process. I believe that a partnership could be mutually beneficial as we work together to establish a strong presence in this new region.\nCould we schedule a quick chat to discuss our potential collaboration? I''d value your insights and guidance.\nLooking forward to the opportunity to connect!', '2024-10-28 03:10:12', '2024-10-28 03:10:12'),
(11, '54f6616e-9aba-4988-9b28-d773b23f8093', 'MUKESH KHANAL', 'mukhanal@gmail.com', '9761808290', 'buying an electrical heater FIHP20D', 'Hi,\nI keep calling on both numbers but the call is not going through. I wish to buy the FIHP20D and had a couple of questions. Please call back when you can. Thanks.', '2024-11-24 05:43:19', '2024-11-24 05:43:19'),
(12, 'aa54782b-d2a4-491c-ad18-7615919f4111', 'Katie Nguyen', 'katie@innorix.com', '0867936563', 'Sigma Technologies X Innorix', 'Hi there,\n\nI’m Katie, Business Development Manager from Innorix. With 25 years of experience in vision AI cameras and more than 5000 customers around the world, we have collaborated with leaders in various industries.\n\nAs we expand our business scope to Nepal, we believe that a partnership with your company can strengthen our potential growth that vibrates the market.\n\nLet me set up a quick meeting with you to discuss our potential partnership this week.\n\nAll the best,', '2024-12-23 05:34:24', '2024-12-23 05:34:24'),
(13, 'aa5b1b40-be23-4840-a761-8d3575e0cdfe', 'Mark Loveland', 'mark.loveland@smithandbyford.com', '07790619891', '2A Sefton Road', 'Hi, We have one of you hot water cylinders ( Sigma 500) install on one of our service sites. It is leaking from the bolt holed flange on the top of the cylinder. Would you be able to provide a contact/supplier who would be able to supply the gasket for this water heater please?', '2025-02-24 09:14:03', '2025-02-24 09:14:03'),
(14, '930ae345-8940-477e-ad4b-8dbf6f59b1b7', 'Ravi Solanki', 'exportsales@amrutenergy.com', '+916353532240', 'Greetings from Amrut Energy Private Limited - Manufacturer of Water Pumps (Solar & Electric), Solar Panel & Solar Street Light', 'Dear Sir/Madam,\nGreetings from Amrut Energy Pvt. Ltd.!\nWe Amrut Energy is a leading Manufacturer of Solar Water Pumps, Solar Panels (Poly & Mono Crystalline), Solar Street Lights & Electrical Water Pumps in India.\nWe have dealers & distributors network all over in India, also we have 12 Warehouses across India.\nAlso we are exporting in South Africa, Australia, Italy, Nepal, Bangladesh, Oman, Saudi Arabia, Sri Lanka, Uganda, Kenya & Tanzania.\nAlso I am sharing our Company Profile and Brochures along with Technical Details for your reference. If you have any questions, please feel free to contact us. We are providing the best quality solutions for your needs at qualitative rates.\nLooking for your positive reply to start a long lasting business relation with your organization.\nAlso Please do share your Contact / What’s App details for smooth communication.\n\nThanks & Regards;\nRavi', '2025-04-16 01:27:03', '2025-04-16 01:27:03'),
(15, '971b4a69-a3bf-4f65-916e-781167c442c6', 'Vicky yang', 'vicky@wttor.com', '+8618532595119', 'fire warning equipment-linear heat detector', 'Dear Sigma Technologies Pvt. Ltd.，\n\nI noticed your company is related to fire warning equipment, and we’d like to propose a partnership.\nAs a sales manager at Hebei Weitan Technology (Mecro Detect),we provide Distributed temperature sensing system,Digital Type Linear Heat Detector- UL Certified and Intelligent Optical Fiber Temperature Measuring Device with competitive price andgood quality.\nAttached is our catalog. Let me know you if you’d like to discuss further.\n\nBest regards\nVicky yang\nWhatsApp +8615100511295\n         +8618532595119\nTel:+8618532595119\nWebsite: www.hbwttor.com', '2025-07-31 20:25:03', '2025-07-31 20:25:03'),
(16, '259116a5-eebd-461a-8130-dfaf24db7acc', 'Omkarnath Kaushal', 'uvraajkaushal305@gmail.com', '9700363152', 'Application for job', 'I want to work in your company. I have several years of experience in sales and Service if there is any requirement then I will happy to send my CV', '2026-06-12 12:13:01', '2026-06-12 12:13:01');
