INSERT INTO "faqs" ("id", "slug", "user_id", "question", "answer", "type_id", "name", "email", "phone_number", "status", "created_at", "updated_at") VALUES
(1, '91c20cae-72da-48a8-9110-a702a998b716', 1, 'What size of pool is this heat pump suitable for?', 'The size of the pool the Swimming Pool Heat Pump is suitable for depends on the specific model and its heating capacity. We offers various models with different heating capacities to accommodate a range of pool sizes.', 1, NULL, NULL, NULL, 1, '2024-03-18 01:22:35', '2024-03-19 06:03:50'),
(2, 'e41a6b8d-bb6a-4ea9-b3ab-a82996231b2a', 1, 'Are there any warranties or guarantees for Innmotek products?', 'Yes, we stand behind the quality and reliability of our products/services. We offer warranties and guarantees to ensure your peace of mind. Specific warranty details can be found on the product/service pages or obtained by contacting our support team.', 1, NULL, NULL, NULL, 1, '2024-03-19 06:04:28', '2024-03-19 06:04:28'),
(3, 'f130f849-b8f9-4218-a3f8-1ccc2e5fb0d4', 1, 'How can I stay updated on the latest developments and offerings from Innmotek?', 'To stay informed about our latest products, services, and company news, visit our website''s "News" or "Blog" section. You can also subscribe to our newsletter for regular updates delivered to your inbox.', 1, NULL, NULL, NULL, 1, '2024-03-19 06:04:51', '2024-03-19 06:04:51'),
(4, '5dff315b-8c85-4ee5-9099-2191a12915f1', 1, 'What is the pricing structure for Innmotek products ?', 'Our pricing varies depending on the type and quantity of products/services you require. For detailed pricing information, please reach out to our sales team, and they will provide you with a quote tailored to your needs.', 2, NULL, NULL, NULL, 1, '2024-03-19 06:05:14', '2024-03-19 06:05:14'),
(5, '0053d0d3-fda6-4a74-947a-da8ad362817f', 1, 'Does it need a lot of space to be installed?', 'The monobloc aerothermal heat pump is a very compact air-conditioning system, so the technical room is very simple and small in size. The installation consists of an outdoor unit and an indoor unit. The great advantage of the aerothermal system is that it avoids duplicating systems as it produces heating and cooling.', 3, NULL, NULL, NULL, 1, '2024-03-19 06:05:40', '2024-03-19 06:05:40'),
(6, '37e537cb-8c04-482c-b923-5152051a193a', 1, 'How does this system achieve great saving if it uses electricity?', 'Heat pumps use energy to run the compressor, a component of the heat pump, but this electricity consumption is minimal compared to the energy that is extracted from the air in the case of aerothermal energy and from the ground or water in the case of geothermal energy. The heat pump can generate from 1 kW of electricity consumed up to 5 kW of useful thermal energy for the air conditioning of the house. Thanks to these high efficiencies, large savings can be achieved.', 3, NULL, NULL, NULL, 1, '2024-03-19 06:06:03', '2024-03-19 06:06:03'),
(7, '6f9b520b-d4c6-40d6-b422-982432c71ab5', 1, 'What is a monobloc aerothermal heat pump?', 'It is a type of aerothermal heat pump in which all the components of the heat pump are in the outdoor unit, making it a very compact and easy to install system. The indoor unit usually has different models, some more basic ones consisting only of the control screen and others more complex with hydraulic kits and even domestic hot water tanks.', 3, NULL, NULL, NULL, 1, '2024-03-19 06:06:23', '2024-03-19 06:06:23'),
(8, '773adb6e-0367-428c-992b-9e0bd50ac7fc', 1, 'What is the difference between air conditioning and aerothermal energy?', 'Air conditioning is a type of aerothermal heat pump of the air-air type, this means that it extracts energy from the air and transmits it to the interior of the installation through the air, so air conditioning cannot be used with underfloor heating, radiators and cannot heat DHW. In addition, air conditioning is less efficient, more polluting due to the large amount of refrigerant it uses, and more expensive to maintain. The monobloc aerothermal heat pump is of the air-water type, as it exchanges heat with the outside air and transmits it to the inside via water. Monobloc refers to the fact that all the components of the aerothermal heat pump are located in the outdoor unit.', 3, NULL, NULL, NULL, 1, '2024-03-19 06:06:46', '2024-03-19 06:06:46'),
(9, 'a357052e-56e0-459d-9259-4b8042c4a845', 1, 'Can the house be cooled in summer and heated in winter with aerothermal energy?', 'One of the great advantages of the heat pump is the ability to heat, cool and domestic hot water (DHW) with the same equipment. The aerothermal heat pump extracts heat from the air in winter to heat the installation and the DHW. In summer, the aerothermal heat pump transports the heat inside the house to the outside, thus reducing the temperature.', 3, NULL, NULL, NULL, 1, '2024-03-19 06:07:06', '2024-03-19 06:07:06');
