INSERT INTO "pages" ("id", "slug", "user_id", "title", "description", "image", "status", "summary", "seo_title", "seo_keyword", "seo_description", "created_at", "updated_at") VALUES
(1, 'privacy-policy', 1, 'Privacy Policy', '<p>Thank you for choosing Sigma Technologies. We appreciate your trust, and we are committed to protecting your privacy. This Privacy Policy outlines how we, Sigma Technologies, collect, use, maintain, protect, and disclose information when you visit our website. By accessing or using the Website, you agree to the terms of this Privacy Policy.</p><p> If you do not agree with our practices, please refrain from using our Website. Information we collect at Sigma Technologies, we collect various types of information from and about our users, including: Personal Information: We collect identifiable information such as your name, email address, postal address, and phone number, provided voluntarily by you. Non-personal Information: We also collect non-personal information about your visit, such as pages viewed, links clicked, and other actions taken within our Website. How we use your information, We, at Sigma Technologies, use the information we collect for several purposes, including: </p><ul><li>To enhance your experience by presenting our Website and its contents to you. </li><li>To provide information, products, or services requested by you. </li><li>To fulfill any other purpose for which you provide the information. </li><li>To carry out our obligations and enforce our rights arising from any contracts entered into between you and us. </li><li>Disclosure of Your Information We respect your privacy. </li></ul><p>At Sigma Technologies, we do not sell, trade, or transfer your personally identifiable information to outside parties. Trusted third parties may assist us in operating our Website, conducting business, or servicing you, as long as they agree to maintain the confidentiality of your information. We may also disclose your personal information to comply with any court order, law, or legal process, including responding to government or regulatory requests. Your security is important to us. At Sigma Technologies, we have implemented measures to protect your personal information from accidental loss and unauthorized access, use, alteration, and disclosure. Changes to our Privacy Policy We, at Sigma Technologies, may update our Privacy Policy periodically. Material changes to how we treat your personal information will be communicated through the updated Privacy Policy posted on this page. Contact Information If you have any questions or concerns about this Privacy Policy, please reach out to us at [Your Contact Information]. </p><p>By using the Sigma Technologies Website, you consent to this Privacy Policy.</p>', NULL, 1, NULL, 'Privacy Policy - Sigma Technologies', NULL, NULL, '2024-03-18 01:49:40', '2024-09-24 04:17:35'),
(2, 'terms-and-condition', 1, 'Terms & Condition', '<p style="text-align: justify;">Welcome to Sigma Technologies, your trusted provider of high-quality products. Please read the following terms and conditions carefully as they govern your use of our website and your purchase of our products. By accessing or using our website, you agree to be bound by these terms and conditions.<br> 1. General Terms: These terms and conditions govern the sale of products and your use of the website operated by Sigma Technologies Pvt. Ltd.<br> </p><p style="text-align: justify;">2. Products and Services<br>Product Availability: All products listed on our website are subject to availability. We reserve the right to modify or discontinue any product without notice.<br>Product Descriptions: We strive to provide accurate product descriptions. However, we do not guarantee that product descriptions or other content are error-free.</p><p style="text-align: justify;"><br>3. Returns and Refunds<br>Return Policy: You may return products of receipt for a full refund/exchange, provided they are unused, in their original packaging, and accompanied by proof of purchase.<br>Non-Returnable Items: The following items cannot be returned:<br>- Products that have been used or damaged<br>- Items marked as final sale<br>- Customized or special-order items<br><br>4. Limitation of Liability<br>We are not liable for any indirect, special, incidental, or consequential damages arising from the use or inability to use our products. Our maximum liability shall be limited to the purchase price of the product.<br><br>5. Intellectual Property<br>All content on our website, including text, images, logos, and product information, is the property of Sigma Technologies and is protected by intellectual property laws. You may not reproduce or distribute any content without our prior written consent.<br><br>6. Privacy<br>Please refer to our [Privacy Policy] for information on how we collect, use, and protect your personal data.<br><br>7. Changes to Terms<br>We reserve the right to modify these Terms at any time. Changes will be posted on our website, and it is your responsibility to review them periodically.<br><br>8. Contact Information<br>For any queries regarding these Terms, please contact us at:<br><br><span style="font-size: 14px;">Sigma Technologies Pvt. Ltd. <br>Aspen Marg, Maitighar, St. Xavier College Rd</span></p><p style="text-align: justify;"><span style="font-size: 14px;">atul.sigtia@sigmatechnologies.com.np</span></p><p style="text-align: justify;"><br></p>', NULL, 1, NULL, 'Terms & Condition - Sigma Technologies', NULL, NULL, '2024-09-04 17:50:35', '2024-09-24 04:20:20'),
(3, 'home-page', 2, 'Home', NULL, NULL, 1, NULL, 'Sigma Technologies: Innovative Water Treatment & Heating Solutions in Kathmandu, Nepal', NULL, 'Sigma Technologies Pvt. Ltd. provides advanced water treatment and heating solutions in Kathmandu, Nepal. Our expertise includes hot water systems, water filtration, underfloor heating, and fire protection equipment. Discover our industry-leading products, including hot water heat pumps and solar water heaters, designed to enhance comfort and safety in your home or business.', '2024-09-05 08:23:00', '2024-10-15 16:13:56'),
(4, 'about-us', 2, 'About Us', NULL, NULL, 1, NULL, 'About Us - Sigma Technologies', NULL, NULL, '2024-09-05 08:24:27', '2024-09-05 08:24:27'),
(5, 'associations', 2, 'Associations', NULL, NULL, 1, NULL, 'Associations - Sigma Technologies', NULL, 'Discover Sigma Technologies'' extensive network of business affiliations and alliances. The numerous businesses we work with to offer our clients cutting-edge solutions and services are fully described on our associations page.', '2024-09-05 08:26:37', '2024-09-05 08:26:37'),
(6, 'sister-concern', 2, 'Sister Concern', NULL, NULL, 1, NULL, 'Sister Concern - Sigma Technologies', NULL, 'Discover Sigma Technologies'' extensive network of business affiliations and alliances. The numerous businesses we work with to offer our clients cutting-edge solutions and services are fully described on our associations page.', '2024-09-05 08:27:39', '2024-09-05 08:27:39'),
(7, 'products', 2, 'Products', NULL, NULL, 1, NULL, 'Products - Sigma Technologies', NULL, 'Discover Sigma Technologies'' extensive network of business affiliations and alliances. The numerous businesses we work with to offer our clients cutting-edge solutions and services are fully described on our associations page.', '2024-09-05 08:28:49', '2024-09-24 04:26:24'),
(8, 'blogs', 2, 'Blogs', NULL, NULL, 1, NULL, 'Blogs - Sigma Technologies', NULL, NULL, '2024-09-05 08:29:24', '2024-09-24 04:25:30'),
(10, 'blogs-category', 2, 'Blogs Category', NULL, NULL, 1, NULL, 'Blogs - Sigma Technologies', NULL, NULL, '2024-09-05 08:30:18', '2024-09-24 04:24:57'),
(11, 'contact-us', 2, 'Contact Us', NULL, NULL, 1, NULL, 'Contact Us - Sigma Technologies', NULL, NULL, '2024-09-05 08:31:09', '2024-09-05 08:31:09'),
