INSERT INTO "products" ("id", "slug", "title", "user_id", "brand_id", "category_id", "summary", "description", "warranty", "specification", "installation", "download", "image", "seo_title", "seo_description", "seo_keyword", "status", "created_at", "updated_at", "price", "sale_price", "type", "stock", "shops", "daraz_link", "hardware_pasal_link", "mero_pasal_link", "order", "order_status") VALUES
(6, 'air-purifier', 'Air Purifier : K01', 2, 2, 26, NULL, '<p>Looking for a high-quality air purifier that will help you breathe easily and stay healthy? Look no further than the Dr Care Air Purifier K01C.<br><br>Featuring advanced HEPA filtration technology, this air purifier is designed to remove up to 99.97% of airborne particles as small as 0.3 microns. This includes common allergens like pollen, dust, and pet dander, as well as harmful pollutants like smoke and volatile organic compounds (VOCs).<br><br>The Dr Care Air Purifier K01C is also incredibly easy to use, with simple controls and an intuitive interface. You can choose from multiple fan speeds and even set a timer to ensure that your air purifier runs for exactly as long as you need it to.<br><br>But the real standout feature of the Dr Care Air Purifier is its compact, stylish design. This air purifier looks great in any room, and its low-profile design means that it won’t take up much space. Plus, its quiet operation ensures that it won’t disturb you while you’re working, sleeping, or relaxing.<br><br>With its powerful HEPA filtration technology, user-friendly controls, and sleek design, the Dr Care Air Purifier K01C is the perfect choice for anyone who wants to breathe easily and stay healthy. So why wait? Order yours today and experience the benefits for yourself!<br></p>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoicing. An original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in the picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', NULL, '<p><br></p>', NULL, 'daa326ea-e1af-4c57-9c41-d7f5c23d9f55.webp', 'Air Purifier K01C- Activated Carbon Ionizer | Sigma Technologies', 'Looking for a high-quality air purifier to keep your indoor air clean and healthy? Look no further than Dr Care Air Purifier K01C! Our advanced air purification technology is designed to remove pollutants and allergens from your home or office, leaving you with fresh, breathable air. With easy-to-use controls and a sleek, modern design, the K01C is the perfect choice for anyone looking to improve their indoor air quality. Shop now and experience the benefits of clean air with Air Purifier K01C!', NULL, 1, '2024-04-28 08:23:45', '2025-04-09 00:38:53', '14500', NULL, 'Hot', '1', NULL, NULL, NULL, NULL, 125, 0),
(9, 'dehumidifier-dh-752', 'Dehumidifier : DH 752', 2, 9, 27, NULL, '<p><strong>Model No. :<span>&nbsp;</span></strong>DH 752</p><p><strong>DH 752 – 50 Ltrs./day &amp; 260 m3/hr.</strong></p><p>Highly efficient machines are designated to operate in harsh work conditions. Ideal for industry and construction. Sturdy and cost-effective range of portable dehumidifiers ideally suited for projects in the construction industry, restoration jobs, water damage control and more.</p><p><strong>Features:</strong></p><ul><li>Automatic fast defrosting using hot gases</li><li><div>High efficiency</div></li><li><div>Durable casing</div></li><li><div>Simple operation</div></li><li><div>Built-in hygrostat</div></li><li><div>Continuous operation possible (24 h/day)</div></li><li><div>Water tank with automatic shut-off when full</div></li><li><div>Possibility to connect a hose to remove condensed water</div></li><li><div>Hour counter</div></li><li><div>Air filter</div></li></ul><p><strong>Applications:</strong></p><ul><li>Construction</li><li>Flooded buildings and cellars</li><li>Buildings and commercial spaces</li><li>Protection from steam condensation in sewage treatments and waterworks</li><li>Storage rooms</li><li>Equipment Rooms</li><li>Hospitals</li><li>Agriculture</li><li>Waterworks</li><li>Water damage restoration</li><li>Rental companies</li></ul>', NULL, NULL, '<table style="width: 88.306%;"><thead><tr><th><span>Specifications</span></th><th><span>Units</span></th><th><span>DH&nbsp;752</span></th></tr></thead><tbody><tr><td><span>Capacity (30°C/80% RH)</span></td><td><div>l/24h</div></td><td><div>45.6</div></td></tr><tr><td><span>Capacity (20°C/60% RH)</span></td><td><div>l/24h</div></td><td><div>20.3</div></td></tr><tr><td><span>For rooms of approx.</span></td><td><div>m³</div></td><td><div>701</div></td></tr><tr><td><span>For restoration after flood</span></td><td><div>m³</div></td><td><div>280</div></td></tr><tr><td><span>Refrigerant</span></td><td><div>–</div></td><td><div>R290</div></td></tr><tr><td><span>Air flow</span></td><td><div>m³/h</div></td><td><div>350</div></td></tr><tr><td><span>Operating temperature range</span></td><td><div>°C</div></td><td><div>5-35</div></td></tr><tr><td><span>Operating humidity range</span></td><td><div>%</div></td><td><div>20-90</div></td></tr><tr><td><span>Power consumption</span></td><td><div>W</div></td><td><div>900</div></td></tr><tr><td><span>Power supply</span></td><td><div>V/Hz</div></td><td><div>220-240/1ph/50</div></td></tr><tr><td><span>Sound level</span></td><td><div>dB(A)</div></td><td><div>52</div></td></tr><tr><td><span>Compressor</span></td><td><div><br></div><br></td><td><div>Rotary</div></td></tr><tr><td><span>Tank capacity</span></td><td><div>l</div></td><td><div>5.7</div></td></tr><tr><td><span>Product size (l x w x h)</span></td><td><div>mm</div></td><td><div>580 x 422 x 820</div></td></tr><tr><td><span>Box size (l x w x h)</span></td><td><div>mm</div></td><td><div>610 x 405 x 660</div></td></tr><tr><td><span>Net/gross weight</span></td><td><div>kg</div></td><td><div>30/36</div></td></tr><tr><td><span>Pallet</span></td><td><div>pcs</div></td><td><div>12</div></td></tr></tbody></table>', NULL, 'bc7c089c-71e5-437b-9e05-33e562166e0d.webp', 'Dehumidifier : DH 752 - Sigma Technologies', 'DH 752 – condensation dehumidifier Professional condensation dehumidifiers Highly efficient machines designated to operate in harsh work conditions.', NULL, 1, '2024-04-29 05:35:17', '2024-10-03 12:20:26', '149160', NULL, NULL, '1', NULL, NULL, NULL, NULL, 123, 0),
(11, 'dehumidifier-dh-720', 'Dehumidifier : DH 720', 2, 9, 27, NULL, '<p><strong>Model No. :<span>&nbsp;</span></strong>DH 720</p><p><strong>DH 720 – 20 Ltrs./day &amp; 150 m3/hr.</strong></p><p>DH 720 is a general purpose mobile dehumidifier manufactured by Calorex (a Dantherm Group Company). It removes humidity from rooms, prevent mould and bacteria development with an active filter preventing unpleasant odours. These air dehumidifiers can be used in apartments, garages, cellars, libraries, drying rooms, equipment rooms, bathrooms, and other household rooms.</p><p><strong>Features</strong></p><ul><li>Attractive design</li><li>Compact, plastic casing</li><li>Light, easy to transport</li><li>Quiet operation</li><li>Simple controls</li><li>Built in hygrostat</li><li>Tank full indicator</li><li>UV lamp kills bacteria and germs</li><li>Electronic panel control</li></ul><p><strong>Applications</strong></p><ul><li>Humid residential rooms</li><li>House library</li><li>Cellars</li><li>Laundry, drying room</li><li>Pantry</li><li>Collector’s room</li><li>Gallery</li><li>Equipment Room</li><li>Hospital</li></ul>', NULL, NULL, '<table style="width: 93.6612%;"><tbody><tr><td><strong>Specifications</strong></td><td><strong>Units</strong></td><td><strong>DH 720</strong></td></tr><tr><td>Capacity (30°C/80% RH)</td><td>l/24h</td><td>20</td></tr><tr><td>Air flow</td><td>m³/h</td><td>150</td></tr><tr><td>Operating temperature range</td><td>°C</td><td>5-32</td></tr><tr><td>Operating humidity range</td><td>%</td><td>35-95</td></tr><tr><td>Power consumption</td><td>W</td><td>390</td></tr><tr><td>Power supply</td><td>V/Hz</td><td>220-240/1ph/50</td></tr><tr><td>Noise</td><td>dB(A)</td><td>48</td></tr><tr><td>Tank capacity</td><td>l</td><td>5</td></tr><tr><td>Product size (l x w x h)</td><td>mm</td><td>410 x 210 x 550</td></tr><tr><td>Weight</td><td>kg</td><td>11</td></tr></tbody></table>', NULL, 'a6160d79-d5a1-4447-8347-f84ed2b460a9.webp', 'Dehumidifier : DH 720 - Sigma Technologies', NULL, NULL, 1, '2024-04-29 05:40:42', '2024-10-03 11:24:37', '72000', NULL, NULL, '1', NULL, NULL, NULL, NULL, 121, 0),
(12, 'grundfos-all-in-one-pressure-booster-pump-scala1', 'Pressure Booster Pump : SCALA1', 2, 4, 50, NULL, '<p>Model: SCALA1</p><p>Grundfos SCALA1 is an all-in-one pressure booster pump with a high-efficiency motor and hydraulics with low noise operation for domestic water supply and also for light commercial applications. Built-in Bluetooth communication gives you complete control over the pump using the Grundfos GO REMOTE, also for twin pump operation.</p><p>This means that installation and commissioning have never been easier. The Grundfos GO REMOTE app also lets you see alarm status and get easy pump diagnostics. You can create and email reports onsite and access hard-to-reach installations remotely from the app.</p><div><div><div><div><div><div><div><div><p><strong>Application</strong><br>Designed for pressure boosting in domestic installations. Use all-in-one pressure booster pump SCALA1 for:</p><ul><li>pumping from a roof tank, break tank or ground tank</li><li>water supply from shallow wells (less than 8 m.)</li><li>pressure boosting from city mains water.</li></ul><p>For domestic pressure boosting, you get water on demand for:</p><ul><li>taps and showers in the home</li><li>garden and lawn irrigation.</li></ul><p>In addition, SCALA1 is the perfect pressure-boosting solution for light commercial applications such as greenhouses, irrigation, car wash and produce (fruit and vegetable) sections in supermarkets.​</p><p>If a greater flow is required, this is easily done in a twin pump setup with the available accessories (including baseplate, cable and inlet and outlet manifolds).</p></div></div></div></div></div></div></div></div>', NULL, '<p><br></p>', '<p><strong>FIVE SIZE VARIANTS FOR EVERY DOMESTIC WATER SUPPLY NEED</strong></p><p>Designed for pressure boosting in domestic installations, use SCALA1 for pumping from a roof tank,<br>break tank or ground tank. It is also ideal for water supply from shallow wells (less than 8 m) and for<br>pressure boosting from city mains water.</p><table><tbody><tr><td><br></td><td>SCALA1 3-25</td><td>SCALA1 3-35</td><td>SCALA1 3-45</td><td>SCALA1 5-25</td><td>SCALA1 5-55</td></tr><tr><td>Max ambient temperature</td><td>55 °C / 131 °F</td></tr><tr><td>Max liquid temperature</td><td>45 °C / 113 °F</td></tr><tr><td>Max system pressure</td><td>8 bar / 115 psi</td></tr><tr><td>Max inlet pressure</td><td>5 bar / 72 psi</td><td>4 bar / 58 psi</td><td>3 bar / 43 psi</td><td>5 bar / 72 psi</td><td>2 bar / 29 psi</td></tr><tr><td>Max head</td><td>25 m / 82 ft</td><td>36 m / 118 ft</td><td>44 m / 144 ft</td><td>26 m / 85 ft</td><td>52 m / 170 ft</td></tr><tr><td>Nominal head</td><td>15 m / 49 ft</td><td>20 m / 65 ft</td><td>25 m / 82 ft</td><td>15 m / 49 ft</td><td>25 m / 82 ft</td></tr><tr><td>Nominal flow</td><td>3.0 m3/h / 13.2 US GPM</td><td>3.7 m3/h / 16.3 US GPM</td><td>3.6 m3/h / 15.8 US GPM</td><td>4.8 m3/h / 21.1 US GPM</td><td>5.3 m3/h / 23.3 US GPM</td></tr><tr><td>IP Rating</td><td>X4D (outdoor use ready)</td></tr><tr><td>Pumped liquid</td><td>Clean water</td></tr><tr><td>Noise level</td><td>&lt; 55 dB(A)</td></tr><tr><td>Net Weight</td><td>11.4 kg / 25.1 lbs</td><td>11.5 kg / 25.3 lbs</td><td>12.0 kg / 26.5 lbs</td><td>11.5 kg / 25.3 lbs</td><td>14.0 kg / 30.9 lbs</td></tr><tr><td>Suction capability</td><td>max 8 m / max 26 ft</td></tr></tbody></table>', NULL, 'e2e24ac9-b413-47c7-88e2-f6ddb74c971c.webp', 'Pressure Booster Pump : SCALA1 - Sigma Technologies', 'SCALA1 is a fully intergrated, compact self-priming, pressure booster for domestic use. It can communicate with Grundfos GO Remote app via built-in Bluetooth technology enabling high customisation options.', NULL, 1, '2024-04-29 05:42:45', '2026-07-05 04:31:47', '135600', NULL, 'Hot', '1', NULL, NULL, NULL, NULL, 109, 0),
(13, 'scala-2', 'Pressure Booster Pump : SCALA2', 2, 4, 50, NULL, '<p><strong>Grundfos SCALA2</strong><span>&nbsp;</span>is a fully integrated water booster pump delivering perfect water pressure to all taps. It features a pump, motor, tank, sensor, drive, and non-return valve in one compact unit that installs quickly and easily. With its intelligent pump control, SCALA2 adjusts performance to any demand – and with its water-cooled motor, it offers one of the lowest noise levels in its class. The result is maximum comfort with minimum effort.</p><p><strong>Sizing in seconds</strong><br>Sizing and selection have never been easier. SCALA2 handles all boosting needs in residential buildings with up to 3 floors and 8 taps.</p><p><strong>Key features :</strong></p><ul><li>Intelligent pump control.</li><li>Water-cooled, permanent magnet motor.</li><li>Dry running protection.</li><li>Self-priming.</li><li>User-friendly control panel.</li><li>Outdoor-ready.</li></ul><p><strong>APPLICATIONS</strong><span>&nbsp;</span>:</p><ul><li>SCALA2 is designed for residential buildings with up to 3 floors and 8 taps.</li><li>Boosting from mains: Increases the water pressure delivered by city mains.</li><li>Boosting from tanks: Increases water pressure from roof tanks, break tanks, and ground tanks, including rainwater tanks.</li><li>Boosting from wells: Pumps water from a depth of up to 8 meters.</li><li>Indoor and outdoor installation: X4D, Enclosure type 3</li></ul><p><strong>BENEFITS :</strong></p><ul><li>Perfect water pressure: Intelligent pump control adjusts operation to ensure perfect water pressure at all times.</li><li>Low noise: With a noise level of 47 dB(A) in typical use, SCALA2 is one of the quietest boosters in its class.</li><li>Easy selection: One variant for all domestic applications.</li><li>Easy installation: Compact, all-in-one solution for perfect installation in no time.</li><li>Easy to operate: User-friendly control panel for easy set-up.</li></ul>', NULL, '<p><br></p>', '<p><strong>TECHNICAL DATA :</strong></p><ul><li>Flow rate: max. 4 m3/h</li><li>Head: max. 45 m</li><li>Liquid temperature: 45 to 55 °C</li><li>Operating pressure: max. 10 bar.</li></ul>', NULL, '7d966ed8-9d78-4ccf-9a0a-8a549b94c2dc.webp', 'Pressure Booster Pump : SCALA2 - Sigma Technologies', 'The Grundfos Water Pressure Pump Scala2 is a powerful and efficient water pressure booster pump designed for residential and light commercial applications. Whether you need to boost water pressure in your home, office, or small building, the Grundfos Scala2 has the power and reliability you need to get the job done.', NULL, 1, '2024-04-29 05:44:21', '2026-07-05 04:33:42', '166110', NULL, NULL, '1', NULL, NULL, NULL, NULL, 120, 0),
(14, 'hot-water-circulator-pump-comfort-box-90', 'Hot Water Circulator : COMFORT BOX 90', 2, 4, 52, NULL, '<p><strong>GRUNDFOS HOT WATER CIRCULATOR PUMP – COMFORT BOX 90</strong></p><p>Comfort Box is a fully integrated, compact system for hot-water circulating and pressure boosting in domestic applications. It includes control of media temperature, time delay and tap-water pulse trigger.</p><p>The Grundfos Comfort Box, with its external appearance inspired by cobblestone, helps to create a simple quick water-use experience for people who seek a pleasant and cheerful existence. “Wash as you wish,” this home-appliance-like box is most suited to providing quick hot water to homes in large flats, small villas, and duplexes with 100-150m pipeline length, particularly for people who value life quality and interior design.</p><p>The Grundfos Comfort Box is a completely integrated, small system for increasing pressure and circulating hot water in household applications. It has controls for media temperature, time delays, time programmes, and tap water pulse triggers.</p><p>Comfort Box can be installed in three easy steps:<br>1. Mount the box on the wall. 2. Connect the pipes. 3. Connect the pump to the power supply.</p><p>After the installation, perform a quick start setup and switch on the pump to activate the system.</p><p><strong>Grundfos Comfort Box has the following components necessary to ensure feeding instant hot water:</strong></p><ul><li>Intelligent controller</li><li>Integrated diversity of pipe connections</li><li>High-efficiency and low-noise pump</li><li>Integrated temperature and flow-switch sensor</li></ul><p><strong>Features</strong></p><ul><li>Hot-water circulation</li><li>Low noise, &lt; 47 dB(A) (in typical use)</li><li>Compact</li><li>Robust and reliable</li><li>Easy installation</li><li>Dry-running/lock-rotor protection</li></ul>', NULL, NULL, '<div><div><table><tbody><tr><td>Product name</td><td>Comfort Box 90-D-PI-B-1-STD</td></tr><tr><td>Product No</td><td>99437312</td></tr><tr><td>EAN number</td><td>5713829104273</td></tr></tbody></table></div><div><h3>Technical</h3><table><tbody><tr><td>Maximum flow</td><td>1.5 m³/h</td></tr><tr><td>Maximum head</td><td>9 m</td></tr></tbody></table></div><div><h3>Materials</h3><table><tbody><tr><td>Pump housing</td><td>Cast iron</td></tr><tr><td>Cabinet</td><td>Plastic</td></tr></tbody></table></div></div><div><div><h3>Installation</h3><table><tbody><tr><td>Range of ambient temperature</td><td>0 .. 40 °C</td></tr><tr><td>Type of connection</td><td>G ext. – G int.</td></tr><tr><td>Size of connection</td><td>3/4 – 1/2 inch</td></tr><tr><td>Earth connection</td><td>PE</td></tr></tbody></table></div><div><h3>Liquid</h3><table><tbody><tr><td>Liquid temperature range</td><td>0 .. 70 °C</td></tr></tbody></table></div><div><h3>Electrical data</h3><table><tbody><tr><td>Power input P1</td><td>120 W</td></tr><tr><td>Mains frequency</td><td>50 Hz</td></tr><tr><td>Rated voltage</td><td>1 x 220 V</td></tr><tr><td>Rated current</td><td>0.48 A</td></tr><tr><td>Enclosure class (IEC 34-5)</td><td>IP20</td></tr></tbody></table></div><div><h3>Others</h3><table><tbody><tr><td>Net weight</td><td>4.24 kg</td></tr><tr><td>Gross weight</td><td>5.47 kg</td></tr></tbody></table></div></div>', NULL, '4b1431ec-60b2-4b54-ba4e-4dce43055800.webp', 'Sentence length: Great! - Grundfos Nepal', 'The Grundfos Hot Water Circulation Pump Comfort Box 90 is the ultimate solution for instant hot water at your fingertips. With its compact design and easy installation process, this pump provides efficient and reliable hot water circulation throughout your home. Enjoy the convenience of hot water on demand and save time, energy, and money with the Grundfos Comfort Box 90.', NULL, 1, '2024-04-29 05:45:55', '2025-01-05 07:44:13', '72500', NULL, NULL, '1', NULL, NULL, NULL, NULL, 119, 0),
(15, 'waste-water-lifting-station', 'Waste Water Lifting Station', 2, 4, 57, NULL, '<p><strong>GRUNDFOS WASTE WATER PUMP– SOLOLIFT2 WC-1</strong></p><p>The Grundfos Waste Water Pump SOLOLIFT2 is a small, compact, ready-to-install automated lifting station with robust cutting systems incorporated. The lifting station is appropriate for pumping wastewater including excrement from residential houses. C-3 and D-2 are only for grey wastewater without faeces.</p><p>The Sololift2 WC-1 is intended to pump wastewater from a toilet containing toilet paper and faeces and is equipped with an additional connection on the lid, such as a washbasin.</p><p>Pumping additional elements into liquids may produce defects and limit the reach of our guarantee.</p><p>The Sololift2 WC-1 is frequently used to dewater a toilet and washbasin in basements below sewage level as part of the repair or modernization of existing structures if the site is far from the main soil pipe and a natural slope cannot be constructed.</p><p><strong>Application</strong></p><p>Wherever the drain of a sanitary appliance is required but no gravity drain pipe is available or possible. The units with a WC connection are dedicated to installation in private homes only. Other units can be utilized also for commercial applications.</p><p>The compact lifting station is equipped with the following:</p><ul><li>Cable without plug (see technical data)</li><li>Horizontal or vertical fastening possibility of discharge hose connector with several adaptors for pipes with Ø22-40mm</li><li>Integrated non-return valve</li><li>Dry and high-performance motor unit incl. thermal protection, pressure switch and controller</li><li>DN100 toilet connection hose</li><li>Flexible connectors for inlet (adjustable in height) of pipes Ø36 or 40</li><li>Slot for an alarm board with a buzzer (accessory)</li><li>Manual anti-clogging function and separate drain connection for service</li><li>Venting valve with overflow protection</li><li>Uplift fixation clips</li></ul>', NULL, NULL, '<p><br></p>', NULL, 'eb49c7ed-83df-4fbe-a73e-ad5b119d6351.webp', 'Waste Water Pump : SOLOLIFT2 - Sigma Technologies', 'Looking for a reliable solution to pump waste water from your toilet or bathroom? Look no further than the Grundfos Sololift2 WC-1 wastewater pump! This unique and powerful pump is built to handle even the most demanding wastewater applications, making it suitable for use in homes, flats, and commercial structures. The Grundfos Sololift2 WC-1 is an excellent choice for anybody searching for a high-quality wastewater pump due to its small design, ease of installation, and dependable performance.', NULL, 1, '2024-04-29 05:50:16', '2025-07-14 01:48:30', '80200', NULL, NULL, '1', NULL, NULL, NULL, NULL, 118, 0),
(16, 'water-pumps-cmb-1-27', 'Water Pumps : CMB 1-27', 2, 4, 6, NULL, '<p><strong>CM BOOSTER</strong></p><p><strong>GRUNDFOS CM&nbsp;</strong></p><p><strong>DOMESTIC WATER PRESSURE BOOSTER PUMP</strong></p><p><em><strong>The most robust pump designed for water pressure boosting</strong></em></p><p>The Grundfos CMB woth PT is a compact booster pump designed for domestic and light commercial use. The booster unit consists of a Grundfos CM pump with stainless steel hydraulic components and a pressure tank.</p><p>The CM pump is supplied with a pressure tank for even distribution of water pressure. When the water demand increases, there wil be a pressure deop in the pipeline from the preset level. The pump automatically starts till reaches pre-set sut-off pressure. The system are available with 24 Lts &amp; 60 Lts pressure tank.</p><p><strong>Applications:</strong></p><ul><li>Mains boosting</li><li>Household water supply</li><li>Boosting from above ground water tanks</li></ul><p><strong>Features:</strong></p><ul><li>Silent operation, compact design and highly reliable</li><li>Wide performance range</li><li>Liquid temperature from 20°C upto 120°C (pump only)</li><li>Built-in thermal protection</li><li>F class installation</li><li>100 Start/Stop per hour</li></ul><p><strong>Construction:</strong></p><ul><li>Electro-coated cast iron parts free from corrosion</li><li>High efficient motor</li><li>Horizontal multistage centrifugal pump</li><li>Long life components are of corrosion and wear resistance stainless steel</li></ul>', NULL, NULL, NULL, NULL, 'bf6cda84-50a8-429a-944f-85866ae869cd.webp', NULL, NULL, NULL, 0, '2024-04-29 05:53:21', '2025-10-07 03:42:58', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 117, 0),
(17, 'pressure-booster-pump-cmb-3-37', 'Pressure Booster Pump : CMB 3-37', 2, 4, 50, NULL, '<p><strong>GRUNDFOS&nbsp;CM BOOSTER</strong></p><p><strong>DOMESTIC WATER PRESSURE BOOSTER PUMP</strong></p><p><em><strong>The most robust pump designed for water pressure boosting</strong></em></p><p>The Grundfos CMB woth PT is a compact booster pump designed for domestic and light commercial use. The booster unit consists of a Grundfos CM pump with stainless steel hydraulic components and a pressure tank.</p><p>The CM pump is supplied with a pressure tank for even distribution of water pressure. When the water demand increases, there wil be a pressure deop in the pipeline from the preset level. The pump automatically starts till reaches pre-set sut-off pressure. The system are available with 24 Lts &amp; 60 Lts pressure tank.</p><p><strong>Applications:</strong></p><ul><li>Mains boosting</li><li>Household water supply</li><li>Boosting from above ground water tanks</li></ul><p><strong>Features:</strong></p><ul><li>Silent operation, compact design and highly reliable</li><li>Wide performance range</li><li>Liquid temperature from 20°C upto 120°C (pump only)</li><li>Built-in thermal protection</li><li>F class installation</li><li>100 Start/Stop per hour</li></ul><p><strong>Construction:</strong></p><ul><li>Electro-coated cast iron parts free from corrosion</li><li>High efficient motor</li><li>Horizontal multistage centrifugal pump</li><li>Long life components are of corrosion and wear resistance stainless steel</li></ul>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoicing. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><br></p>', '<p>Pump speed on which pump data are based: 2900 rpm</p><p>Rated flow: 3.1 m³/h</p><p>Rated head: 27.4 m</p><p>Impellers: 4</p><p>Primary shaft seal: AVBE</p><p>Approvals and markings: CE, C-TICK</p><p>Model: A</p><p>Return valve: YES</p><p>Start pressure: PM2</p>', NULL, '6ea0b0c0-6030-4e69-a6b0-880452544338.webp', NULL, NULL, NULL, 1, '2024-04-29 05:55:36', '2025-01-05 07:44:13', '101000', NULL, NULL, '10', NULL, NULL, NULL, NULL, 116, 0),
(18, 'pressure-booster-pump-cmb-5-37', 'Pressuer Booster Pump : CMB 5-37', 2, 4, 50, NULL, '<p><strong>Model No. :<span>&nbsp;</span></strong>CMB 5-37</p><p>A SMALL BOOSTER PUMP WITH GIGANTIC POTENTIAL</p><p>It was once said that great things come in small packages. When you meet the Grundfos CM booster pump for the first time, you’ll certainly agree. This horizontal multistage pump has been created with compactness and modularity as two of its central features. Add reliability and quiet operation to the mix, and another innovative pump solution from Grundfos is born.<br>Centrifugal Modular: The pump is basically composed of a series of interchangeable modules, all of which have been designed to work together seamlessly, regardless of the application.</p><p>&nbsp;<br></p><p><strong>Applications :</strong></p><p>The CM pump is supplied with a pressure tank for constant water pressure. When the pressure drops to the pre-set level, the pump will start-up and when the water consumption drops again, the outlet pressure will rise to a pre-set pressure after which the pump will stop. This is fitted with 24 ltrs. capacity pressure tank.<br>The CM pump with Pressure Manager is used for constant water pressure. It is ideal when space is constraint near the overhead tank. It also has dry-running protection, in case of no water in the pipeline.<br>CMB 5-37 is suitable for a family of 4-6 persons.</p><p><strong>Features :</strong></p><ul><li>Silent operation, compact design, and highly reliable.</li><li>Wide performance range.</li><li>Liquid temperature from 20 oC up to 120 oC (pump only).</li><li>Built-in thermal protection.</li><li>F class installation.</li><li>80 Start / Stop per hour.</li></ul><p><strong>Construction :</strong></p><ul><li>Electro-coated cast iron parts – free from corrosion.</li><li>High efficient motor.</li><li>Horizontal multistage centrifugal pump.</li><li>Long-life components are of corrosion and wear-resistant stainless steel.</li></ul>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of the tax invoice. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty is applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in the picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><br></p>', '<p><strong>TECHNICAL DATA</strong><span>&nbsp;</span>:</p><ul><li>Flow rate: 4 m3/h</li><li>Head: 30 m</li><li>Pressure Tank Size: 24 Ltrs.</li><li>Motor Connected Load: 0.7 KW</li><li>Liquid temperature: 120 °</li><li>Electricals : 230 V, 1 pH, 50 Hz</li><li>Suction Pipe Size: 32 mm</li><li>Delivery Pipe Size: 32 mm</li></ul>', NULL, '161818a0-bf8f-47fe-9771-8db876f9a55d.webp', NULL, NULL, NULL, 1, '2024-04-29 05:57:58', '2025-01-05 07:44:13', '105000', NULL, NULL, '10', NULL, NULL, NULL, NULL, 115, 0),
(19, 'hot-water-circulator-comfort-15-14-ba-pm', 'Hot Water Circulator : COMFORT 15-14 BXA PM', 2, 4, 52, NULL, '<p>The Grundfos COMFORT range is designed for re-circulation of domestic hot water in small family houses. The COMFORT PM range is a high efficiency choice with an energy usage of only 8 W. The intelligent COMFORT AUTO<em>ADAPT&nbsp;</em>PM automatically adapts to the individual’s hot water consumption pattern in the household and only runs when hot water is needed.</p><p><strong>Features:</strong></p><ul><li>Minimise water waste</li></ul><p>Every year, a eypical family of three living in a household with a conventional one string plumbing system, pours up to 16,000 Lts of clean water straight down the drain as they wait for the water to run hot. The COMFORT PM pump delivers instantly hot water, which in average amounts to 60 seconds- or 0.15 litres of wasted water per second. The tangible result of the COMFORT PM pump lower costs while incresing the comfort.</p><ul><li>AUTO<em>ADAPT</em><span>&nbsp;</span>mode</li></ul><p>The COMFORT pump learns from the user pattern and automatically adapts to guarantee the best comfort and the highest energy savings.</p><ul><li>Temperature control mode</li></ul><p>The water temperature is kept within a calculated range in the individual system, ensuring that the pump runs only when required to save energy.</p><ul><li>100% mode</li></ul><p>The pump operates continuously at full speed.</p>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoicing. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><br></p>', '<p><strong>Technical Data</strong></p><ul><li>System pressure : 10 bar</li><li>Liquid Temperature : 2 to 110 °C</li><li>Ambient Temperature : 40 °C</li><li>Relative : 95%</li><li>Mains voltage : 1 x 240V, 50 Hz</li><li>Enclosure class : IP44</li><li>Insulation class : F</li><li>Sound pressure level : 43 dB</li><li>Approvals and markings : AS4020</li></ul>', NULL, 'd60c73b2-e6fa-4510-9ade-57323f747d39.webp', NULL, NULL, NULL, 1, '2024-04-29 05:59:54', '2026-04-10 05:39:43', '42500', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 114, 0),
(20, 'grundfos-hot-water-circulator-pump-magna3', 'Hot Water Circulator : Magna3 25-80', 2, 4, 52, NULL, '<p><strong>GRUNDFOS HOT WATER CIRCULATOR PUMP – MAGNA3</strong></p><p>TAKING PUMP INTELLIGENCE TO THE NEXT LEVEL</p><p>The Grundfos MAGNA3 is a circulator pump with a permanent magnet motor that will fit both heating, cooling and domestic hot water circulation, making it the obvious choice for almost any building project old or new. With its unrivalled efficiency, all-encompassing range and built-in communication capabilities plus functionalities replacing system components, the MAGNA3 is ideal for building owners, engineers and specifiers looking to create high-performance systems for buildings.</p><p>The MAGNA3 is the premium choice when system control and monitoring are key. MAGNA3 supports Fieldbus by optional CIM modules and connects directly with the Grundfos GO app via Bluetooth.</p><p>The MAGNA3 is a pump with no maintenance requirements and with extremely low Life Cycle Cost.</p><p><strong>APPLICATIONS</strong></p><ul><li><a href="https://www.sigmatechnologies.com.np/product-category/heating-solutions-nepal/">Heating</a></li><li>Air-conditioning</li><li>Cooling</li><li><a href="https://www.sigmatechnologies.com.np/product-category/heating-solutions-nepal/hot-water-heat-pump/">Domestic heat pump</a></li></ul><p><strong>FEATURES</strong></p><ul><li><strong>BEST EFFICIENCY:<span>&nbsp;</span></strong>The best EEI on the market reduce energy costs by up to 75%.</li></ul><ul><li><strong>HIGH INTELLIGENCE:<span>&nbsp;</span></strong>The new FLOW LIMIT<em>&nbsp;</em>and FLOW ADAPT functions along with the renowned<span>&nbsp;</span><em>AUTOADAPT<span>&nbsp;</span></em>enable complete system control.</li></ul><ul><li><strong>EASY INSTALLATION:<span>&nbsp;</span></strong>Intuitive user interface saves time during installation.</li></ul><ul><li><strong>VERSATILE APPLICATION:<span>&nbsp;</span></strong>The pump handles liquids from -10°C to 110°C independent of the ambient temperature — to make it suitable for both heating and cooling projects.</li></ul><ul><li><strong>BMS SYSTEM</strong></li></ul><p><strong>Suitable for:</strong></p><ul><li><a href="https://product-selection.grundfos.com/applications/commercial-buildings/commercial-air-conditioning" rel="external noopener noreferrer">Commercial air conditioning</a></li><li><a href="https://product-selection.grundfos.com/applications/commercial-buildings/commercial-heating" rel="external noopener noreferrer">Commercial heating</a></li><li><a href="https://product-selection.grundfos.com/applications/domestic-buildings/domestic-hot-water-recirculation" rel="external noopener noreferrer">Domestic hot water recirculation</a></li><li><a href="https://product-selection.grundfos.com/applications/domestic-buildings/domestic-heating" rel="external noopener noreferrer">Domestic heating</a></li><li><a href="https://product-selection.grundfos.com/applications/district-energy/district-cooling" rel="external noopener noreferrer">District cooling</a></li><li><a href="https://product-selection.grundfos.com/applications/district-energy/district-heating" rel="external noopener noreferrer">District heating</a></li><li><a href="https://product-selection.grundfos.com/applications/industrial-temperature-control/industrial-heating" rel="external noopener noreferrer">Industrial heating</a></li></ul><p><br></p>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoicing. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><br></p>', '<p><strong>Technical Data</strong></p><p>Rated flow: 4.5 m³/h</p><p>Rated head: 5.649 m</p><p>Head max: 80 dm</p><p>TF class: 110</p><p>Approvals on nameplate: CE, VDE, EAC, CN ROHS, WEEE</p><p>Model: D</p>', NULL, '24d63a56-5afe-475e-b1a1-b7578397194f.webp', NULL, NULL, NULL, 1, '2024-04-29 06:01:23', '2026-04-10 05:42:47', '125000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 113, 0),
(22, 'water-pumps-ups-15-60-130', 'Hot Water Circulator : UPS 15-60 130', 2, 4, 52, NULL, '<p>The pump is of the canned rotor type, i.e. pump and motor form an integral unit without shaft seal and with only two gaskets for sealing. The bearings are lubricated by the pump liquid. The pump has 3-step speed selector.</p><p>The pump is characterized by:</p><ul><li>Ceramic shaft and radial bearings.</li><li>Carbon axial bearing.</li><li>Stainless steel rotor can and bearing plate.</li><li>Corrosion-resistant impeller, Composite, PES/PP.</li><li>Cast iron pump housing.</li></ul><p>The motor is a 1-phase motor.</p><p>No additional motor protection is required.</p><p><strong>Liquid:</strong><br>Pumped liquid: Water<br>Liquid temperature range: 2 .. 110 °C<br>Liquid temperature during operation: 60 °C<br>Density: 983.2 kg/m³</p>', '<p><strong>Warranty:</strong><span>&nbsp;12&nbsp;months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoicing. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><strong>Installation:</strong></p><p>Amb. max at 80 dgr C liquid: 40 °C<br>Maximum operating pressure: 10 bar<br>Pipe connection: G 1<br>Pressure rating: PN 10<br>Port-to-port length: 130 mm</p><p><strong>Electrical data:</strong></p><p>Power input in speed 1: 50 W<br>Power input in speed 2: 60 W<br>Max. power input: 70 W<br>Mains frequency: 50 HzRated voltage: 1 x 230 V<br>Current in speed 1: 0.22 A<br>Current in speed 2: 0.27 A<br>Current in speed 3: 0.3 A<br>Capacitor size – run: 2.5 μF<br>Enclosure class (IEC 34-5): IP44<br>Insulation class (IEC 85): F</p><p><strong>Others:</strong></p><p>Net weight: 2.3 kg<br>Gross weight: 2.5 kg<br>Shipping volume: 0.004 m³</p>', '<p><strong>Technical:</strong></p><p>TF class: 110<br>Approvals on nameplate: VDE,AAA,EAC</p><p><strong>Materials:</strong></p><p>Pump housing: Cast iron<br>EN-JL1030<br>ASTM 30 B<br>Impeller: Composite, PES/PP</p><p><br></p>', NULL, '2c92c9f5-d673-464a-b456-61880bee4819.webp', NULL, NULL, NULL, 1, '2024-04-29 06:04:31', '2026-04-10 05:42:03', '42900', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 112, 0),
(23, 'pressure-booster-pump-upa-120', 'Pressure Booster Pump : UPA 120', 2, 4, 50, NULL, '<p><strong>DOMESTIC HOME BOOSTERS</strong></p><p>The Grundfos UPA range is a revolution in pump applications. This small pump unit provides you with the luxury of sustained water pressure at any time of the day. The modern and unique design of the pump also ensures operation safety and a longer life span. It’s the fullest pump potential at a fraction of the size.</p><p>Features:</p><ul><li><span>In-Line single shower booster pump&nbsp;</span></li><li><span>Completely automatic through the flow switch</span></li><li><span>Easy installation: plug and play</span></li><li><span>Space-saving design</span></li><li><span>Silent Operation</span></li></ul>', '<p><strong>Warranty:</strong>&nbsp;12&nbsp;months</p><p>1. Warranty :<br>– Warranty applies from the date of tax invoicing. Original Tax Invoice is required for any warranty claim.<br>– Warranty applicable as per manufacturer standard terms of conditions.<br>2. Actual product may vary as in picture displayed.<br>3. Manufacturer may change the specifications at any time.</p>', '<p><br></p>', '<p><strong>TECHNICAL DATA</strong><span>&nbsp;</span>:</p><ul><li>Flow rate : 1.2 to 2.0 m3/h</li><li>Head: 10 to 8 m</li><li>Motor Connected Load: 235 watts</li><li>Liquid temperature: 60 ° C</li><li>Electricals : 230 V, 1 pH, 50 Hz</li><li>Suction Pipe Size: 20 mm</li><li>Delivery Pipe Size: 20 mm</li></ul>', NULL, 'f6d775f5-b6ed-44df-914b-a9cde53f4c33.webp', NULL, NULL, NULL, 1, '2024-04-29 06:05:35', '2026-01-26 11:05:37', '42500', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 111, 0),
(24, 'water-transfer-pumps-jp-5', 'Water Transfer Pumps : JP-5', 2, 4, 51, NULL, '<p>Model: JP-5</p><p><strong>Water Lifting &amp; Transfer Pump</strong></p><p><strong>Applications :</strong><br>The JP pump is a horizontal, self-priming, centrifugal pump for pumping clear water and other non-aggressive liquids. Horizontal self-priming jet pump. Self-priming single-stage centrifugal jet pump with axial suction port and radial discharge port close-coupled with a single-phase motor with thermal overload protection. The pump and motor are mounted on a common baseplate. The pump has a mechanical carbon/ceramics shaft seal.&nbsp;This compact unit, which can be used in a fixed position or transported as required, is easy to maintain and is simple as well as economical to run. It is particularly recommended for water transfer applications.</p><p><strong>Features :</strong></p><ul><li>Self-priming pump</li><li>Suction head up to 8 meters</li><li>Maximum operating pressure: 6 bar</li><li>Carry handle</li><li>Single-phase models supplied with supply cable, power plug, and start/stop switch.</li><li>Maximum ambient temperature: +55°C</li><li>Voltages: Voltages: 1×230 V, 50 Hz or 3×400 V, 50 Hz</li></ul><p><strong>Construction :</strong></p><ul><li>The stainless steel pump housing and impeller.</li><li>Paint application by electrophoresis ensures the motor has excellent corrosion resistance.</li><li>IP 44 motor. Insulation class F.</li><li>Single-phase models effectively protected against any accidental overload by built-in thermal protection in the terminal box.</li></ul>', '<p><strong>Warranty:</strong><span>&nbsp;12 months</span><br><br><span>1. Warranty : &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty applies from the date of tax invoice. Original Tax Invoice is required for any warranty claim.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>&nbsp; &nbsp; &nbsp;– Warranty is applicable as per manufacturer standard terms of conditions.&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;</span><br><span>2. Actual product may vary as in the picture displayed.&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><br><span>3. Manufacturer may change the specifications at any time.</span><br></p>', '<p><br></p>', '<p><strong>Characterstics :</strong></p><p>Flow: 2 m3/hr.<br>Head: 27 mtrs.<br>Electricals : 1 x 230-240 V, 50 Hz<br>Connected Load: 775 watts<br>Pump Housing : SS304<br>Impeller : SS304</p>', NULL, 'dcb1b0a1-6991-4ef8-ab63-8425a54e5860.webp', NULL, NULL, NULL, 1, '2024-04-29 06:06:44', '2025-02-17 23:26:53', '58545', NULL, 'Promo', '10', NULL, NULL, NULL, NULL, 110, 0);
INSERT INTO "products" ("id", "slug", "title", "user_id", "brand_id", "category_id", "summary", "description", "warranty", "specification", "installation", "download", "image", "seo_title", "seo_description", "seo_keyword", "status", "created_at", "updated_at", "price", "sale_price", "type", "stock", "shops", "daraz_link", "hardware_pasal_link", "mero_pasal_link", "order", "order_status") VALUES
(27, '200lpi200', 'Thermosiphon Thermal Solar Water Heater – Open Loop : 200 Ltrs.', 2, 6, 19, NULL, '<p><strong>Model No. :<span>&nbsp;</span></strong>200LPI200</p><p><strong>Open Loop solar water heater : 200 Ltrs.</strong></p><p>200 Ltr. Capacity with one collector, Solarflame MAX Thermosiphon, Non-Pressurized System, Open Loop, enameled, 4bars, 9006 external cover / 3Kw-220V / 2 Mg anode rods, 1980X1010X86mm size, selective Absorber / Copper water frame 8xΦ12×0,5mm + 2xΦ22×0,7mm / Glass fiber 30mm / Low iron glass 3,2mm /Alum. Frame RAL9006 / 4 exits, support structure for flat roof installation/40°, flexible connections’ set for inox tubes.</p><p><strong>Thermosyphon closed loop solar systems “Solar Flame MAX” with the following benefits:</strong><br>✓ Large range of versions (49 systems), certified according to SOLAR KEYMARK.<br>✓ Compact system setup, for easy transport and installation.<br>✓ Customized design, for exclusive OEM versions.</p><p><strong>Tank:</strong><br>➢ Glass-dual enameled (according to DIN4753, part 3) double walled (with large jacket heat exchanger) boilers, with optimized heat insulation and durable external cover for maximum protection in seaside areas.</p><p><strong>The collectors:</strong><br>Superb efficiency rating collectors “Solar Flame FMAX” (η0,a=83% according to EN12975 Standard) series with:<br>➢ High selective PVD absorber coating, for fast and high temperature production.<br>➢ Water frame entirely made of copper.<br>➢ Tempered Hail-resistant solar low iron glass.<br>➢ Maximum heat transfer between the absorber sheet and the copper water frame, thanks to optimized laser welding technology.<br>➢ Incident angle modifier Kθ =0.96 at 50° ensures maximum radiation absorption throughout the day.<br>➢ High quality, recyclable materials ensure a long service life and high environmental compatibility.</p><p><strong>The support structures:</strong><br>➢ Support structures with high endurance and easy installation on flat or inclined tiled surfaces.<br>➢ Easy and safe installation due to special high quality and reliable accessories included in the connections’ kit.</p><p><strong>Make<span>&nbsp;</span></strong>: Solarflame MAX</p>', NULL, NULL, '<p><strong><u>Technical Specifications</u></strong></p><p><strong>Thermosyphon closed loop solar systems “Solar Flame MAX” with the following benefits:</strong><br>✓ Large range of versions (49 systems), certified according to SOLAR KEYMARK.<br>✓ Compact system setup, for easy transport and installation.<br>✓ Customized design, for exclusive OEM versions.</p><p><strong>Tank:</strong><br>➢ Glass-dual enameled (according to DIN4753, part 3) double walled (with large jacket heat exchanger) boilers, with optimized heat insulation and durable external cover for maximum protection in seaside areas.</p><p><strong>The collectors:</strong><br>Superb efficiency rating collectors “Solar Flame FMAX” (η0,a=83% according to EN12975 Standard) series with:<br>➢ High selective PVD absorber coating, for fast and high temperature production.<br>➢ Water frame entirely made of copper.<br>➢ Tempered Hail-resistant solar low iron glass.<br>➢ Maximum heat transfer between the absorber sheet and the copper water frame, thanks to optimized laser welding technology.<br>➢ Incident angle modifier Kθ =0.96 at 50° ensures maximum radiation absorption throughout the day.<br>➢ High quality, recyclable materials ensure a long service life and high environmental compatibility.</p><p><strong>The support structures:</strong><br>➢ Support structures with high endurance and easy installation on flat or inclined tiled surfaces.<br>➢ Easy and safe installation due to special high quality and reliable accessories included in the connections’ kit.</p><p><strong>Thermal Solar Collector :</strong></p><table><tbody><tr><td><strong>Overall Dimensions<span>&nbsp;</span></strong>: 1980 x 1010 x 86 mm</td></tr><tr><td><strong>Frame of the collector :</strong><span>&nbsp;</span>Aluminium profile powder coated for maximum protection in seaside areas.</td></tr><tr><td><strong>Absorber surface :</strong><span>&nbsp;</span>Aluminium surface with blue titanium high selective treatment with absorbence and low emission (Alpha = 95%, beta = 4%), laser welded on the copper water frame.</td></tr><tr><td><strong>Transparent Cover :</strong><span>&nbsp;</span>Security-Tempered prismatic solar glass for maximum protection against extreme weather conditions and temperature changes.</td></tr><tr><td><strong>Header of water frame :<span>&nbsp;</span></strong>Copper tubes dia 22mm, which is welded to the vertical tubes with hard silver solder. Each water frame is tested at the pressure of 15 bars. Headers are punched with upper expansion for perfect fitting with vertical tubes and minimum pressure drop in the collector.</td></tr><tr><td><strong>Thermal insulation :<span>&nbsp;</span></strong>40mm thock layer of prepressed black mineral wool special for solar panels for minimum thermal loss. Rockwool insulation thermal conductivity : 0=0.035 W/m<span>&nbsp;</span><sup>o</sup>K (EN13162) and heat capacity 0.84 kJ/kgK.</td></tr><tr><td><strong>Back Cover :</strong><span>&nbsp;</span>Aluzinc 0.4mm thick. Aluzinc stands for aluminium and zinc, fused in almost equal proportions, as a coating for the steel sheet that is coated with a silvery spangle composed of Aluminium (55%), Zinc (43.4%) and a touch of silicon (1.6%). Great mechanical strength and 7 times more resisted to corrosion than common galvanized steel.</td></tr><tr><td><strong>Sealing Materials<span>&nbsp;</span></strong>: For perfect waterproof finish and proper ventilation of collectors casing, all materials used (EPDM, polyurethane sealant) resist to extreme weather conditions and temperature changes.</td></tr></tbody></table>', NULL, '8d668b2d-b553-43e7-9922-fc7da3f5b281.webp', NULL, NULL, NULL, 1, '2024-04-29 06:20:05', '2025-10-06 23:24:17', '112000', NULL, NULL, '5', NULL, NULL, NULL, NULL, 106, 0),
(28, '300max400', 'Thermosiphon Thermal Solar Water Heater – Closed Loop : 300 Ltrs.', 2, 10, 19, NULL, '<p><strong>Model No. :<span>&nbsp;</span></strong>300MAX400</p><p><strong>Closed Loop solar water heater : 300 Ltrs.</strong></p><p>300 Ltrs. Thermosiphon solar water heater with 2 colectors, Pressurized System, Closed Loop System, enameled, Closed Loop, 10 Bar, 9006 external cover / 3Kw-220V / 2 Mg anode rods / with Port for Inlet and Otlet for Heat Pump, 1980X1010X86mm alum. selective Absorber / Copper water frame 9xΦ8×0,4mm + 2xΦ22×0,7mm / Rock fiber 40mm / Low iron glass 3,2mm /Alum. Frame RAL9006 / 4 exits, support structure for flat roof installation, accessories for support structure for flat roof installation/40°, connections’ set for inox tubes/ 12Lt thermal fluid, Ports for Heat Pumps Φ20</p><p><strong>Make : Solarflame MAX</strong></p>', NULL, NULL, '<p><strong><u>Technical Specifications</u></strong></p><p><strong>Thermosyphon closed loop solar systems “Solar Flame MAX” with the following benefits:</strong><br>✓ Large range of versions (49 systems), certified according to SOLAR KEYMARK.<br>✓ Compact system setup, for easy transport and installation.<br>✓ Customized design, for exclusive OEM versions.</p><p><strong>Tank:</strong><br>➢ Glass-dual enameled (according to DIN4753, part 3) double walled (with large jacket heat exchanger) boilers, with optimized heat insulation and durable external cover for maximum protection in seaside areas.</p><p><strong>The collectors:</strong><br>Superb efficiency rating collectors “Solar Flame FMAX” (η0,a=83% according to EN12975 Standard) series with:<br>➢ High selective PVD absorber coating, for fast and high temperature production.<br>➢ Water frame entirely made of copper.<br>➢ Tempered Hail-resistant solar low iron glass.<br>➢ Maximum heat transfer between the absorber sheet and the copper water frame, thanks to optimized laser welding technology.<br>➢ Incident angle modifier Kθ =0.96 at 50° ensures maximum radiat