(204, 'shower-filter-shower-filter', 'Shower Filter (Shower Filter)', 1, 7, 68, NULL, '<p>Reduce Chlorine and lead from the incoming water that could cause skin allergies</p><ul><li>Filter cartridge model: SFKCO1-CN1<br></li><li>Efficient removal rating at 50 micron<br></li><li>Efficient capacity at 50,000 liters*<br></li><li>Flow rate at 8.0 LPM<br></li><li>Reducing Chlorine and lead from the incoming water after that could cause a skin allergy<br></li><li>Tested in accordance with NSF 177 <br></li><li>FDA CFR-21 compliant materials<br></li></ul>', NULL, NULL, NULL, NULL, '176ac3a7-c4c7-4c74-b4df-22922e508751.webp', NULL, NULL, NULL, 1, '2025-10-08 01:16:38', '2025-10-08 01:16:38', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(205, 'ap-902-whole-house-water-filter', 'AP-902 (Whole House Water Filter)', 1, 7, 68, NULL, '<p>Whole House water filter to remove sediments, particulate, sand, and rust down to 5 microns to provide cleaner water for all purposes.</p><ul><li>Pleated PP Technology</li><li>Filter cartridge model: AP910R<br></li><li>Efficient removal rating at 5 micron<br></li><li>Efficient capacity at 300,000 liters*<br></li><li>Flow rate at 75.7 LPM<br></li><li>304 Stainless steel filter head for outdoor installation<br></li><li>Sanitary Quick Change (SQC) Design <br></li><li>NSF 42 certified and FDA CFR-21 compliant materials<br></li></ul>', NULL, NULL, NULL, NULL, 'b235ee8f-c447-498f-8a0a-bc14b06267a6.webp', NULL, NULL, NULL, 1, '2025-10-08 01:22:39', '2025-10-08 01:22:39', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(206, 'ap11-t-pre-filter', 'AP11-T (Pre Filter)', 1, 7, 68, NULL, '<p>Pre-Cartridge filter to be used before the drinking water filter with a 5 micron rating.</p>', NULL, NULL, NULL, NULL, '45778b1d-a446-4800-907c-5e32327ca27e.webp', NULL, NULL, NULL, 1, '2025-10-08 01:28:43', '2025-10-08 01:28:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(207, 'ias-190-drinking-water-filter', 'IAS-190 (Drinking Water Filter)', 1, 7, 68, NULL, '<p>Water Filter for Drinking Water applications with larger requirements in schools, hostels, restaurants, hotels, offices, and industries</p><ul><li>IMPACT Technology<br></li><li>Efficient removal rating at 0.2micron<br></li><li>Efficient capacity at 2,00,000 liters*<br></li><li>Flow rate at 18.9 LPM<br></li><li>Select VOCs: reduction for Atrazine, Benzene, Carbofuran, Dichlorobenzene, Lindane, Toxophene<br></li><li>Sanitary Quick Change (SQC) design<br></li><li>NSF 42,53 certified and FDA CFR-21 compliant materials </li></ul>', NULL, NULL, NULL, NULL, 'b48cedc5-6d79-40c7-9e36-1ddbaa2ea0f7.webp', NULL, NULL, NULL, 1, '2025-10-08 01:37:10', '2025-10-08 01:37:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(208, 'brew120-ms-coffee-and-tea-machine-filter', 'Brew120-MS (Coffee & Tea Machine Filter)', 1, 7, 68, NULL, '<p>Water Filter for Coffee &amp; Tea Machines. Make good Tastes and provide high-quality water.</p><ul><li>IMPACT Technology <br></li><li>Efficient removal rating at 0.5micron<br></li><li>Efficient capacity at 34,069 liters*<br></li><li>Flow rate at 5.7 LPM<br></li><li>Select VOCs: reduction for Atrazine, Benzene, Carbofuran, Dichlorobenzene, Lindane, Toxophene<br></li><li>Sanitary Quick Change (SQC) design<br></li><li>NSF 42,53 certified and FDA CFR-21 compliant materials <br></li></ul>', NULL, NULL, NULL, NULL, 'e4cb84d6-0ab3-4600-ac63-9ea4bac06713.webp', NULL, NULL, NULL, 1, '2025-10-08 01:46:24', '2025-10-08 01:46:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(209, 'ice120-s-ice-machine-water-filter', 'ICE120-S (Ice Machine Water Filter)', 1, 7, 68, NULL, '<p>Water Filter for Ice Machine. Combines cyst, sediment,&nbsp; and chlorine taste and odor reduction, while reducing the effects of chlorine corrosion and scale for up to 34,069 liters.</p><ul><li>IMPACT Technology <br></li><li>Efficient removal rating at 0.5micron<br></li><li>Efficient capacity at 34,069 liters*                                                            <br></li><li>Flow rate at 5.7 LPM<br></li><li>Select VOCs: reduction for Atrazine, Benzene, Carbofuran, Dichlorobenzene, Lindane, Toxophene<br></li><li>Sanitary Quick Change (SQC) design<br></li><li>NSF 42,53 certified and FDA CFR-21 compliant materials <br></li></ul>', NULL, NULL, NULL, NULL, '3308c61e-9f66-47de-8e52-f9641c91e5ab.webp', NULL, NULL, NULL, 1, '2025-10-08 01:54:14', '2025-10-08 01:54:14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(210, '2-wheeler-parking-systems', '2 Wheeler Parking Systems', 1, NULL, 39, NULL, '<p><strong>The Dependent 2- Wheeler Stack Parking System</strong><br></p><p>This mechanical parking system creates parking spaces for 6 bikes/scooters, three at the ground level and another three on the platform above. The lower bike/car needs to be driven out to use the upper platform. This system guarantees trouble-free parking and retrieval of the vehicle in a multi-level parking setup.<br></p><p><strong>Key Benefits:</strong><br></p><ul><li>Ideal for residential buildings and commercial projects<br></li><li>Increases the capacity of underground multi-level parking spaces at hospitals, malls, cinema halls, hotels, etc.<br></li><li>It can also be used as an outdoor mechanical parking system<br></li><li>Provides 6 spaces in the footprint of 3 bikes/scooters<br></li><li>The amount of space used can be reduced by up to 50 percent compared to conventional parking spaces<br></li><li>Leaves space for additional amenities<br></li><li>Accommodates bikes/scooters safely<br></li><li>Protection from theft and damage<br></li><li>Sequential vertical movement of a platform<br></li><li>Simple key switch controls<br></li><li>Optimal access times</li></ul>', NULL, NULL, NULL, NULL, '82095f2a-73ef-4b14-8caa-3f6060c9727e.webp', NULL, NULL, NULL, 1, '2025-10-12 00:12:05', '2025-10-12 00:12:05', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(211, 'grundfos-smart-sub', 'Grundfos Smart-Sub', 1, 4, 51, NULL, '<p>The&nbsp;Grundfos&nbsp;"Smart Sub"&nbsp;(Smart Submersible)&nbsp;is a pump specifically made for open wells and various water sources, and it is provided in both single-phase and three-phase horizontal submersible configurations.&nbsp;The term "smart" could imply its energy efficiency and high-tech features, akin to the&nbsp;SmART SUB HOS&nbsp;model, which has efficient motors and the latest intelligent pumps that possess capabilities such as dry-run safeguard and superior voltage handling that minimize operational problems and maintenance.</p>', NULL, NULL, NULL, NULL, '80ac4ae2-8f9f-430d-b31d-7642c947751a.webp', NULL, NULL, NULL, 1, '2025-10-12 03:51:00', '2025-10-12 03:54:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(212, 'AQUA PAC (AP) Dual-Function Anaerobic Tank', 'AQUA PAC AP', 5, 16, 76, NULL, '<p><span>Anaerobic Combined Septic Tank: The combined septic and filter sections are combined. Suitable for wastewater treatment that occurs from all parts of homes and small offices. Which the treated water will meet the quality of the community effluent, can be discharged To public water sources without causing pollution to Natural water resources.</span></p><p><span><span>Relies on the process of decomposing organic matter in wastewater Anaerobic, with waste water from various indoor activities flowing into the AQUA PAC tank in the first part, which is responsible for separating heavy sediment Clear water and lighter sediment apart Only the clear water will flow to the anaerobic filter. There will be anaerobic bacteria living in the bottom of the tank floating along the gap. And clings to the surface of the plastic intermediate to decompose the remaining organic matter again Get the waste water as according to the standard of the community effluent flow out the top of the tank into the drain</span></span></p>', NULL, NULL, '<p>AQUA AP is a packaged compact treatment plant consisting of septic and anaerobic filter chamber in one tank consisting of Polyethylene (PE) tank body which should be Load &amp; Vacuum Tested as per US/ EU/ Canadian/ Japanese Standard, PE anticlogging Plastic Media, Aqua Seed to enhance the micro organism digestion efficiency, Super Flex pipe joints to protect pipe from cracking caused by land subsidence. It''s working standard should be certified by ISO9001.</p>', NULL, '782b3c7f-e2fc-49b3-9691-32bb42b8176b.webp', NULL, NULL, NULL, 1, '2026-06-11 01:33:23', '2026-06-12 10:46:23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(213, 'ONG Trap', 'Oil & Grease Trap', 5, 16, 78, NULL, '<p>Advanced Oil &amp; Grease Trap</p>', NULL, NULL, NULL, NULL, 'cfdd7979-8e44-41b7-9339-9d123166cc4d.webp', NULL, NULL, NULL, 1, '2026-06-12 04:07:15', '2026-06-12 04:07:15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(214, 'Oil & Grease Trap Under Sink Unit', 'Oil & Grease Trap Under Sink Unit', 5, 16, 78, NULL, '<p>Oil and Grease trap for both undersink &amp; below the ground unit</p>', NULL, NULL, NULL, NULL, 'e58a525b-6032-485b-8c18-975872cf46d2.webp', NULL, NULL, NULL, 1, '2026-06-12 04:10:11', '2026-06-12 04:10:11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(215, 'AC-INT ( NBRF) STP', 'AC-INT ( NBRF) STP', 5, 16, 79, NULL, '<p>Jokhasau Model</p>', NULL, NULL, NULL, NULL, '9edc0c2a-93ad-4a34-afe3-1d2832056de4.webp', NULL, NULL, NULL, 1, '2026-06-12 04:12:23', '2026-06-12 04:12:23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(216, 'AQUA PAC ST-BF Aerobic STP', 'AQUA PAC ST-BF Aerobic STP', 5, 16, 77, NULL, '<p>Compact STP Aerobic Model</p>', NULL, NULL, NULL, NULL, 'dc9cb9cc-3cbf-4aec-a5e1-137ac0c15d72.webp', NULL, NULL, NULL, 1, '2026-06-12 04:16:30', '2026-06-12 04:16:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(217, 'UNSU', 'Oil & Grease Separator SS304 (Under-sink Unit)', 5, 6, 78, NULL, '<p>SS304 Grease Trap&nbsp;</p>', NULL, NULL, NULL, NULL, '1f441db0-e89c-4660-80bc-bf10adf433eb.webp', NULL, NULL, NULL, 1, '2026-06-12 11:16:45', '2026-06-12 11:16:45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0),
(218, 'Undersink Unit', 'Oil & Grease Trap', 5, 16, 78, NULL, '<p>Grease Trap Under Sink Unit</p>', NULL, NULL, NULL, NULL, '9c588b8a-16ce-41a4-884d-a739a76cde96.webp', NULL, NULL, NULL, 1, '2026-06-12 11:19:24', '2026-06-12 11:19:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0);
